            [items addObject:@{
                @"icon": S(entry->icon),
                @"title": S(entry->title),
                @"subtitle": S(entry->subtitle),
            }];
        }
    }
    if (items.count == 0) return nil;

    return @{ @"headline": S(headline), @"items": [items copy] };
}
